// 1 player hud color
// changes the air gauge color

subi r1, r1, 0x20
mr r3, r26
addi r4, r1, 0x10
bl _CheckEXLoadHUDColors
lwz r4, 0x14 (r1) // ex load index
cmplwi r4, 0
beq- lbl_00032194_nonexload
slwi r5, r4, 2
lwz r4, 0x10 (r1)
b lbl_00032194

.global lbl_00032194_nonexload
