lbz r4, 0xBB (r26)
cmpwi r4, 0x12 // chaos emerald
bne- lbl_00032194_nonsuper
lis r4, SuperFormHUDColors@ha
addi r4, r4, SuperFormHUDColors@l
b lbl_00032194

