crmove 4*cr1+eq, 4*cr0+eq // save to cr1
beq- lbl_C243568C_end
lwz r3, 0x0(r4) // load timer
cmpwi r3, 30 // half a second
bge- lbl_C243568C_end
addi r3, r3, 0x1
stw r3, 0x0(r4) // increment timer
li r0, 0x0 // force pause not to trigger
