.global lbl_Z_Y_IgnoreTurbulence
lbl_Z_Y_IgnoreTurbulence:
// C2468D54
// C240F4E8
// r31 = bool ignoreTurbulence

lbz r3, 0xBD(r28) // AI bool
extsb. r3, r3 // if AI
bne- lbl_0006D054
lis r3, CurrentGameMode@ha
lwz r3, CurrentGameMode@l(r3)
// if gamemode == 0x258 or 0x12c or 0x64 or 0x320 or 0x2bc, goto start, otherwise skip
cmpwi   r3,0x258 
beq     lbl_Z_Y_IgnoreTurbulence_start
bge     lbl_Z_Y_IgnoreTurbulence_switch 
cmpwi   r3,0x12c 
beq     lbl_Z_Y_IgnoreTurbulence_start 
bge     lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick
cmpwi   r3,0x64 
beq     lbl_Z_Y_IgnoreTurbulence_start
b       lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick

.global lbl_Z_Y_IgnoreTurbulence_switch
lbl_Z_Y_IgnoreTurbulence_switch:
cmpwi   r3,0x320 
beq     lbl_Z_Y_IgnoreTurbulence_start
bge     lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick
cmpwi   r3,0x2bc 
beq     lbl_Z_Y_IgnoreTurbulence_start
b       lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick

.global lbl_Z_Y_IgnoreTurbulence_start
lbl_Z_Y_IgnoreTurbulence_start:
extsb. r3, r31 # check for whether the gear already has "ignore turbulence" special flag
bne- lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick
lbz r31, 0x8 (r28)
// lwz r3, 0x0(r28) // input pointer
// lwz r4, 0x8(r3) // hold buttons
// andbool r4, r4, 0x800 // AND with 0x800 (Z button) in bool form
// lwz r3, 0xC(r3) // toggle buttons
// andbool r3, r3, 0x8 // AND with 0x8 (Y button) in bool form
// lbz r5, 0x1068(r28) // Y toggle bool in player data
// xor r3, r3, r5 // update Y toggle bool
// stb r3, 0x1068(r28)
// xor r31, r3, r4 // check whether Z or Y cancel each other out, save to: bool ignoreTurbulence
// stb r31, 0x8(r28) // save to player data

.global lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick
lbl_Z_Y_IgnoreTurbulence_slidebooster_gimmick:
lwz r3, 0xE90(r28) // player turbulence index
lis r4, InGamePlayerCount@ha
lwz r4, InGamePlayerCount@l (r4)
cmpw r3, r4
bge- lbl_0006D054 // check for babylon garden big turbulence
lis r4, players@ha
addi r4, r4, players@l
mulli r3, r3, 0x1080 // player struct size
add r4, r3, r4
lbz r3, 0xBB(r4) // check if player is near slide booster's turbulence
cmpwi r3, 0xD // slide booster
bne- lbl_0006D054
li r31, 0 // set bool ignoreTurbulence to false

