.global lbl_C24693FC
lbl_C24693FC:
// jump charge dependent on weight
stwu r1, -0x90 (r1)
stw r0, 8 (r1)
mflr r0
stw r0, 0xC (r1)
stmw r3, 0x10 (r1)
lfs f1, 0x994 (r30) // weight
lis r3, data_C24693FC@ha
addi r3, r3, data_C24693FC@l
lfs f2, 0x4 (r3)
fsubs f1, f1, f2 // get multiplier amount
lfs f2, 0x10 (r3) // check if negative number
fcmpo cr0, f1, f2
bge- other_multiplier
lfs f2, 0x14 (r3) // different multiplier
b 0x8

.global other_multiplier
other_multiplier:
lfs f2, 0 (r3) // get multiplier
fmuls f1, f1, f2
lfs f2, 0x8 (r3)
fadds f1, f1, f2 // max jump charge
lfs f5, 0xC (r3) // calculate other jumps
fsubs f2, f1, f5 // really good jump charge
fsubs f3, f2, f5 // mid jump charge
lbz r4, 0xBB (r30)
cmpwi r4, 0x22 // super hang on
beq sho_and_trickster
lbz r4, 0xBB (r30)
cmpwi r4, 0xE // legend
beq skip_sho
lbz r4, 0x107C (r30)
cmplwi r4, 0x8 // trickster
bne skip_sho

sho_and_trickster:
lfs f5, 24 (r3) // load 0.5
fmuls f1, f1, f5
fmuls f2, f2, f5
fmuls f3, f3, f5

.global skip_sho
skip_sho:
fctiwz f1, f1 // convert them to int
fctiwz f2, f2
fctiwz f3, f3
li r3, -4
stfiwx f1, r3, r1
lwz r4, -0x4 (r1)
stfiwx f2, r3, r1
lwz r5, -0x4 (r1)
stfiwx f3, r3, r1
lwz r6, -0x4 (r1)
srwi r7, r4, 1 // worst jump charge
stb r4, 0x107 (r30) // absolute max jump charge
lbz r0, 0x107C (r30) // archetype
subfic r0, r0, 0x8 // trickster
cntlzw r0, r0
srwi r0, r0, 5
#slwi r0, r0, 1
slw r4, r4, r0
stw r4, 0x14 (r1)
stb r5, 0x104 (r30) // really good jump
stb r6, 0x105 (r30) // mid jump
stb r7, 0x106 (r30) // horrible jump
lbz r3, 0x107 (r30) // max jump charge
lha r4, 0x9F4 (r30) // current jump charge
subi r3, r3, 1
#cmpw r3, r4
#bne- lbl_C24693FC_end
#lis r3, 0xA932
#addi r3, r3, 0xE00 // max jump charge sfx
#bl PlayAudioFromDAT

cmpw r3, r4 # compare maxJC to currJC
bne- lbl_C24693FC_tricksterMax
lis r3, 0xA932
addi r3, r3, 0xE00 // max jump charge sfx
bl PlayAudioFromDAT

.global lbl_C24693FC_tricksterMax
lbl_C24693FC_tricksterMax:
lbz r0, 0x107C(r29)
cmpwi r0, 8
bne- lbl_C24693FC_end
mulli r3, r3, 2
cmpw r3, r4 # compare maxJC*2 to currJC
bne- lbl_C24693FC_end
lis r3, 0xA932
addi r3, r3, 0xE00 // max jump charge sfx
bl PlayAudioFromDAT

.global lbl_C24693FC_end
lbl_C24693FC_end:
lwz r0, 0xC (r1)
mtlr r0
lwz r0, 8 (r1)
lmw r3, 0x10 (r1)
lwz r1, 0 (r1)
blr

