// C247186C
// faster trick speeds dependent on jump charge, on legend

lbz r3, 0xBB (r29)
cmpwi r3, 0xE // legend
bne- lbl_shinobi_tricks
lhz r3, 0x9F4 (r29) // jump charge
lbz r5, 0x107 (r29) // max jump charge
cmpw r3, r5
ble- 0x8
mr r3, r5
mulli r3, r3, 0xA
add r4, r4, r3
b lbl_00075B6C_2

.global lbl_shinobi_tricks
lbl_shinobi_tricks: // faster trick speeds dependent on jump charge, on shinobi
lbz r3, 0xBB (r29)
cmpwi r3, 0x38 // shinobi
bne- lbl_C247186C_trickster
lhz r3, 0x9F4 (r29) // jump charge
lbz r5, 0x107 (r29) // max jump charge
cmpw r3, r5
ble- 0x8
mr r3, r5
mulli r3, r3, 0xA
add r4, r4, r3
b lbl_00075B6C_2

.global lbl_C247186C_trickster
lbl_C247186C_trickster:
lbz r3, 0x107C (r29)
cmpwi r3, 0x8
bne- lbl_00075B6C_2
lhz r3, 0x9F4 (r29) // jump charge
lbz r5, 0x107 (r29) // max jump charge
sub r3, r3, r5
#addi r3, r3, 10 // extra 10 frames for tricksters so they head into overcharge faster
cmpwi r3, 0
ble- lbl_00075B6C_2
lbz r9, 0xBE (r29) # Gear type
cmpwi r9, 0
bne- 0x10 # if not a board, check for bike
// board trickspeed multiplier (x20)
mulli r3, r3, 0x14
add r4, r4, r3
b lbl_00075B6C_2

cmpwi r9, 2 # check for bike
bne- 0x10 # if 2, it's a bike. If not, it's a skate (1)
// bike trickspeed multiplier (x18)
mulli r3, r3, 0x12
add r4, r4, r3
b lbl_00075B6C_2

// skate trickspeed multiplier (x22)
mulli r3, r3, 0x16
add r4, r4, r3
b lbl_00075B6C_2

