.global GetSuperAuraDetail_OLD
GetSuperAuraDetail_OLD:
stwu r1, -0x20 (r1)
mflr r0
stw r0, 0x24 (r1)
stw r31, 0xC (r1)
mr r31, r4
addi r4, r1, 0x10
