lis r4, texList_CustomParticles@ha
addi r4, r4, texList_CustomParticles@l
stw r3, 0 (r31)
stw r4, 0x4 (r31)

4:
lwz r31, 0xC (r1)
lwz r0, 0x24 (r1)
mtlr r0
addi r1, r1, 0x20
blr

