.global lbl_func_UnlockAll
lbl_func_UnlockAll:
// This function unlocks everything in the game (stages, gears, etc)
stwu r1, -128(r1)
stw r0, 8(r1)
mflr r0
stw r0, 132(r1)
stmw r3, 12(r1)
lis r3, GameData@ha
addi r31, r3, GameData@l
addi r3, r31, 0x2
li r4, 0x1 // byte to set
li r5, 0x12 // how many bytes
bl memset
li r3, 0x1
stb r3, 0x18 (r31)
li r3, 0x7
stb r3, 0x347 (r31)
addi r3, r31, 0x348
li r4, 0x1 // byte to set
li r5, 0x69 // how many bytes
bl memset
// mission mode unlocks
li r3, 0x50
mtctr r3
addi r3, r31, 0x18
li r4, 1

.global lbl_func_UnlockAll_loop
lbl_func_UnlockAll_loop:
stwu r4, 0x8 (r3)
bdnz lbl_func_UnlockAll_loop
lwz r0, 132(r1)
mtlr r0
lwz r0, 8(r1)
lmw r3, 12(r1)
lwz r1, 0(r1)
blr

