.global lbl_C253A558
lbl_C253A558:
// Can't Pick E10G In Tag Mode, Other Character Slots Are Greyed Out
// This handles whether it allows you to press the A button on the character slot or not
cmpwi r4, 0x16
bgt- lbl_C253A558_skip
cmpwi r4, 0x10 // e10b slot
beq- lbl_C253A558_skip2
cmpwi r4, 0xF // e10g
bne- lbl_0013E874
lis r3, StartOfObjectsPointer@ha
lwz r3, StartOfObjectsPointer@l (r3)
lwz r3, 0x90 (r3) // object 1 of the game state object
lbz r3, 0x3C (r3) // current game mode
cmpwi r3, 0x7
bne- lbl_0013E874
mr r3, r14
bl IsAnyE10EXLoad
cmpwi r3, 0
bne- lbl_0013E874
b lbl_C253A558_skip2

.global lbl_C253A558_skip
lbl_C253A558_skip:
cmpwi r4, 0x17
bne- lbl_C253A558_skip2
lis r3, str_PXCO@ha
addi r3, r3, str_PXCO@l
bl DVD_ConvertPathToEntrynum
cmpwi r3, 0
bge- lbl_0013E874

.global lbl_C253A558_skip2
lbl_C253A558_skip2:
lis r3, 0xa900
addi r3, r3, 0x400
