.global lbl_0013E874
lbl_0013E874:
// called when pressing the A button on a character slot
mr r3, r14
bl IsAnyE10EXLoad
cmpwi r3, 0
beq- lbl_0013E874_3
lbz r0, 0xBA (r14)
cmpwi r0, 0xF
bne- lbl_0013E874_2
li r0, 0x10
stb r0, 0xBA (r14) // switch to e10b character id upon ex loading other e10 variants
stb r0, 0xBF (r14)
b lbl_0013E874_2

