// Convert every 7 stars on CSS to 1 cyan/green star
stwu r1, -0x10 (r1)
stw r14, 0xC (r1)
mflr r0
stw r0, 0x14 (r1)
li r14, 0 // reset loop counter
cmpwi r15, 7 // check if cyan stars need to be created
blt- lbl_C253BAD0_end

.global lbl_C253BAD0_loop
lbl_C253BAD0_loop:
subi r15, r15, 7
addi r14, r14, 1 // add cyan star
cmpwi r15, 7
blt- lbl_C253BAD0_init_other_loop
b lbl_C253BAD0_loop

.global lbl_C253BAD0_init_other_loop
lbl_C253BAD0_init_other_loop:
add r4, r15, r14
cmpwi r4, 8
blt- lbl_C253BAD0_loc_0x0
mulli r6, r14, 7
add r6, r6, r15 // collective star amount
cmpwi r6, 49
blt- lbl_C253BAD0_skip_to_other_calc
li r14, 7 // cap out the stars at max cyan star amount
li r15, 0
b lbl_C253BAD0_loc_0x0

.global lbl_C253BAD0_skip_to_other_calc
lbl_C253BAD0_skip_to_other_calc:
subi r6, r4, 7 // calculate how many stars needs to be shaved for it to fit

.global lbl_C253BAD0_other_loop
lbl_C253BAD0_other_loop:
mr. r15, r15 // cmp to 0
ble- lbl_C253BAD0_shave_cyan_stars
subi r15, r15, 1 // shave yellow star
subi r6, r6, 1
mr. r6, r6
ble- lbl_C253BAD0_loc_0x0
b lbl_C253BAD0_other_loop

.global lbl_C253BAD0_shave_cyan_stars
lbl_C253BAD0_shave_cyan_stars:
mr. r14, r14
ble- lbl_C253BAD0_end
subi r14, r14, 1 // shave cyan star
addi r15, r15, 7 // convert it to 7 yellow stars
b lbl_C253BAD0_other_loop

